def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]

    # Find rectangular outlines of a single color.
    frames = []
    colors = set(v for row in grid for v in row if v)
    for c in colors:
        pts = [(r, col) for r in range(h) for col in range(w) if grid[r][col] == c]
        r0, r1 = min(r for r, _ in pts), max(r for r, _ in pts)
        c0, c1 = min(col for _, col in pts), max(col for _, col in pts)
        if (r1-r0+1) >= 3 and (c1-c0+1) >= 3:
            if all(grid[r0][j] == c and grid[r1][j] == c for j in range(c0, c1+1)) and \
               all(grid[i][c0] == c and grid[i][c1] == c for i in range(r0, r1+1)):
                frames.append((c, r0, r1, c0, c1))

    # The loose colored marks specify the fill color for the frames.
    mark_colors = [c for c in colors if c not in [f[0] for f in frames]]
    mark_colors.sort(key=lambda c: sum(v == c for row in grid for v in row))

    # Match the groups, from the fewest marks to the smallest interior.
    frames.sort(key=lambda f: (f[2]-f[1]-1)*(f[4]-f[3]-1))
    for (fc, r0, r1, c0, c1), mc in zip(frames, mark_colors):
        for r in range(r0+1, r1):
            for col in range(c0+1, c1):
                g[r][col] = mc if (r-r0-1 + col-c0-1) % 2 == 0 else 0

    # Clear the scattered marks.
    frame_colors = {f[0] for f in frames}
    for r in range(h):
        for col in range(w):
            if grid[r][col] and grid[r][col] not in frame_colors:
                g[r][col] = 0
    return g
